  subgraph cluster_prep {
    label="1. Data \u2014 Search Space \u2014 Controller";
    style=invis;
    clustercolor="#2C3E50";
    padding=12;
    Dataset [
      shape=ellipse,
      fillcolor="#4A90D9",
      strokecolor="#BDD7EE",
      fontcolor="#FFFFFF",
      style=filled,
      penwidth=2,
      width=1.8,
      height=1.0,
      label="Dataset\n(D, X, Y)";
    ];
    HyperSpace [
      shape=box,
      fillcolor="#5B8DEF",
      strokecolor="#AED6F1",
      fontcolor="#FFFFFF",
      style=filled,
      penwidth=1.8,
      width=2.2,
      height=0.8,
