    ];
    KFoldCtrl --> KFods;

    // Detailed example fold
    subgraph cluster_fold1_exp {
      label="Fold 1 \u2014 Expanded Pattern";
      style=invis;
      clustercolor="#E67E22";
      padding=8;
      ExpTrain [shape=cylinder, fillcolor="#3498DB", strokecolor="#A8DFF0", fontcolor="#FFFFFF", style=filled, penwidth=1.4, width=1.6, height=0.9, label="Train Set"];
      ExpTest [shape=circle, fillcolor="#E74C3C", strokecolor="#FAB8C2", fontcolor="#FFFFFF", style=filled, penwidth=1.4, diameter=1.1, label="Test Set"];
      ExpTrainer [shape=prism6, fillcolor="#1ABC9C", strokecolor="#5BE1D1", fontcolor="#FFFFFF", style=filled, penwidth=1.4, width=1.8, height=0.9, label="Train + Validate"];
      ExpModel [shape=hexagon, fillcolor="#6C5CE7", strokecolor="#A29BFE", fontcolor="#FFFFFF", style=filled, penwidth=1.4, width=1.6, height=0.9, label="Model"];
      EvalExp [shape=box, fillcolor="#FDCB6E", strokecolor="#FFEAA7", fontcolor="#7D6608", style=filled, penwidth=1.4, width=1.8, height=0.6, label="Evaluate (metric)"];
      ScoreExp [shape=note, fillcolor="#FBFCDF", strokecolor="#D9D9D9", fontcolor="#444444", style=filled, penwidth=1.2, width=1.6, height=0.7, label="Fold Score"];
      AccExp [shape=box, fillcolor="#BDC3C7", strokecolor="#EBEDED", fontcolor="#2C3E50", style=filled, penwidth=1.4, width=1.5, height=0.7, label="Accumulate this fold"];

      ExpTrain --> ExpTrainer;
      ExpTrainer --> ExpModel;
      ExpModel --> EvalExp;
      ExpTest --> EvalExp;
      EvalExp --> ScoreExp;
      ScoreExp --> AccExp;
      ExpTrain -- ExpTest [style=dashed, color="#EAEAEA", label="data split"];
    }

    // Remaining folds (repeated pattern)
    subgraph cluster_remaining_folds {
      label="Folds 2..k \u2014 Same Pattern";
      style=invis;
      clustercolor="#E67E22";
      Padding=0.5;  // unused to help spacing? Don't use.
      RemFold [
        shape=cloud,
        fillcolor="#F1C40F",
        strokecolor="#F39C12",
        fontcolor="#7D6608",
        style=filled,
        penwidth=1.6,
        width=2.4,
        height=1.3,
        label="Repeated for k\u22121:\ntrain / validate /\nmodel / evaluate";
      ];
