      fillcolor="#2C3E50",
      strokecolor="#7F8C8D",
      fontcolor="#FFFFFF",
      style=filled,
      penwidth=1.8,
      width=1.8,
      height=0.8,
      label="Aggregate Scores\nMean \u00b1 Std";
    ];
    AccExp --> AGG;
    RemFold --> AGG;
  }

  // ---------------- Phase 3: Result ----------------
  subgraph cluster_result {
    label="3. Best Hyperparameters & Report";
    style=invis;
    clustercolor="#27AE60";
    padding=14;
    FINAL [
      shape=diamond,
      fillcolor="#E170E5",
      strokecolor="#AD1457",
      fontcolor="#FFFFFF",
      style=filled,
      penwidth=2,
      width=2.2,
      height=1.3,
      label="Best Hyperparameters\nAverage Performance";
    ];
    REPORT [
      shape=note,
      fillcolor="#9B59B6",
      strokecolor="#E4AEC4",
      fontcolor="#FFFFFF",
      style=filled,
      penwidth=1.6,
      width=2.6,
      height=1.2,
      label="Performance Report\nConfidence intervals,\ncross-validation plots";
    ];
    SELECTED [
      shape=box,
      fillcolor="#27AE60",
      strokecolor="#A5F3C8",
      fontcolor="#FFFFFF",
      style=filled,
      penwidth=1.8,
      width=2.4,
      height=0.8,
      label="Selected Configurations\nfor production/deployment";
    ];
    AGG --> FINAL;
    FINAL --> SELECTED;
    FINAL --> REPORT;
  }
