const std = @import("std");

const MOD: u64 = 33554393;
const MULT: u64 = 252533;
const FIRST: u64 = 20151125;

/// Calcula (base^exp) % mod usando 128 bits para evitar overflow.
fn mod_pow(base: u64, exp: u64, mod: u64) u64 {
    if (exp == 0) return 1 % mod;
    var res: u128 = 1;
    var b: u128 = @intCast(base);
    var e: u64 = exp;
    while (e > 0) {
        if (e & 1) {
            res = (res * b) % mod;
        }
        b = (b * b) % mod;
        e >>= 1;
    }
    return @intCast(res % mod);
}

pub fn main() !void {
    // Lê o conteúdo do arquivo input.txt
    const contents = try std.fs.cwd().readFileAll("input.txt");

    // Remove espaços, tabs e quebras de linha das extremidades
    var trimmed_slice = std.mem.trimSequence(contents, " \t\r\n");
    if (trimmed_slice == null) return;

    const n = std.fmt.parseInt(u64, trimmed_slice.?, 10) catch {
        panic("Entrada inválida.");
    };

    if (n == 0) return;

    // O n-ésimo código é FIRST * MULT^(n-1) mod MOD.
    const mult_pow = mod_pow(MULT, n - 1, MOD);
    const cur = (FIRST * mult_pow) % MOD;

    var writer = std.io.buffer.Writer(std.getstdout());
    try writer.writeFmt("{d}\n", .{cur});
    writer.flush();
}
```

