```
const std = @import("std");
const P: u64 = 33554393;
const M: u64 = 252533;
const A1: u64 = 20151125;

// Modular exponentiation: (base^exp) % mod
fn mod_pow(base: u64, exp: u64, mod: u64) u64 {
    var res: u128 = 1;
    var b: u128 = @intCast(@as(u128, base));
    while (exp > 0) {
        if (exp & 1) res *= @intCast(b);
        b *= b;
        exp >>= 1;
    }
    return @intCast(res % mod);
}

pub fn main() !void {
    const fs = std.fs.cwd();
    const file = try fs.openFile("input.txt", .{ .accessMode = .read });
    defer file.close();

    var reader = std.io.file.Reader(file);
    var line_buf = std.ArrayList(u8).init(std.heap.page_allocator);
    try line_buf.appendSlice("");

    var writer = std.io.buffer.Writer(std.getstdout());

    while (try reader.readAny(&line_buf)) |err| {
        if (err != error.EndOfFile) return err;

        var iter = std.mem.tokenize(u8, line_buf.items, ' ');
        if (iter.len == 0) continue;

        var token = iter.next() orelse continue;
        var trimmed = token.items.trim_to_seq(u8, "\r");
        const s = trimmed;
        const n = std.fmt.parseInt(u64, s, 10) catch {
            std.log.err("Invalid input: {s}", .{s});
            return error.InvalidInt;
        };

        if (n == 0) {
            // If N=0, maybe no code? But at least first? We'll skip.
            try writer.write("0\n");
            continue;
        }

        const m_exp = n - 1;
        const mult_pow = mod_pow(M, m_exp, P);
        const cur = (@as(u64, A1) * mult_pow) % P;
        try writer.writeFmt("{d}\n", .{cur});
    }

    try writer.write("\n");
    writer.flush();
